<script setup>
import {computed,ref,watch} from 'vue'
import SimulationControls from './SimulationControls.vue'
import PropositionalCode from './PropositionalCode.vue'
import {resolutionExamples,validateResolution,resolutionDiagnostic,traceResolution,resolutionCode} from '../services/propositional-inference.mjs'
const preset=ref('rain'),custom=ref(null),step=ref(0),input=ref(''),error=ref('')
watch(preset,()=>{custom.value=null;input.value=JSON.stringify(resolutionExamples.find(e=>e.id===preset.value),null,2);step.value=0;error.value=''},{immediate:true})
const example=computed(()=>custom.value||resolutionExamples.find(e=>e.id===preset.value)),frames=computed(()=>traceResolution(example.value)),state=computed(()=>frames.value[Math.min(step.value,frames.value.length-1)]),diagnostic=computed(()=>resolutionDiagnostic(example.value)),resetKey=computed(()=>JSON.stringify(example.value));watch(resetKey,()=>{step.value=0})
const text=c=>c===null?'Clause hằng đúng':!c.length?'□ · Clause rỗng':c.map(l=>l.replace('!','¬')).join(' ∨ ')
const status={start:'Ghép các clause của KB với phủ định truy vấn.',resolve:'Hợp giải hai clause trên đúng một ký hiệu làm pivot.',tautology:'Resolvent có cả một literal và phủ định của nó, nên luôn đúng. Không cần thêm.',duplicate:'Resolvent đã có, không thêm bản sao.',add:'Thêm resolvent mới và lưu hai clause cha cùng pivot.',success:'Đã có clause rỗng. KB hợp với phủ định truy vấn không thỏa được, nên truy vấn là hệ quả.',saturated:'Đã xét đủ các cặp và pivot mà không sinh clause rỗng. Truy vấn không phải hệ quả của KB.',budget:'Chạm giới hạn thao tác hoặc 80 clause. Chưa kết luận được bằng hợp giải trong bộ xem.'}
function apply(){try{const e=JSON.parse(input.value);validateResolution(e);custom.value=e;step.value=0;error.value=''}catch(e){error.value=e.message}}
</script>
<template><figure class="lab prop-resolution" aria-label="Truy vết hợp giải phản chứng"><label>Ví dụ<select v-model="preset"><option v-for="e in resolutionExamples" :key="e.id" :value="e.id">{{ e.title }}</option></select></label><p>Truy vấn: {{ example.query.replace('!','¬') }}. Mỗi clause là tuyển các literal. Bộ xem xét từng cặp clause và từng pivot, không khử nhiều cặp đối ngẫu cùng lúc.</p><p v-if="!diagnostic.consistent" class="resolution-warning">KB ban đầu đã mâu thuẫn. Chứng minh truy vấn trong trường hợp này là hệ quả của logic cổ điển, không phải bằng chứng rằng tri thức mô tả đúng thế giới.</p><SimulationControls v-model="step" :max="frames.length-1" :reset-key="resetKey"/><p class="resolution-status" role="status">{{ status[state.phase] }}</p><p v-if="state.parents">Cha {{ state.parents.join(' và ') }} · Pivot {{ state.pivot }} · Resolvent {{ text(state.candidate) }}.</p><ol class="resolution-clauses"><li v-for="c in state.clauses" :key="c.id" :class="{active:state.parents?.includes(c.id),empty:!c.literals.length}"><strong>{{ c.id }}: {{ text(c.literals) }}</strong><span v-if="c.parents">Từ {{ c.parents.join(' và ') }}, pivot {{ c.pivot }}.</span><span v-else>{{ c.negatedQuery?'Phủ định truy vấn':'Clause ban đầu' }}.</span></li></ol><details><summary>Kiểm tra độc lập bằng các mô hình</summary><p>{{ diagnostic.models }} mô hình của KB. {{ diagnostic.entails?'Truy vấn đúng trong mọi mô hình của KB.':'Có phản mô hình cho truy vấn.' }}</p><p v-if="diagnostic.counter">Phản mô hình: {{ Object.entries(diagnostic.counter).map(([k,v])=>k+'='+Number(v)).join(', ') }}.</p><p>Phép kiểm tra này dùng riêng bảng chân lý để đối chiếu kết quả, không hướng dẫn bước hợp giải.</p></details><PropositionalCode :code="resolutionCode" :phase="state.phase" :derived="!!state.parents"/><details class="resolution-edit"><summary>Nhập các clause và truy vấn</summary><p>JSON gồm clauses là mảng các mảng literal, query là một literal. Dùng !P cho phủ định. [] là một clause Sai, còn clauses: [] là KB Đúng. Tối đa sáu ký hiệu, 16 clause ban đầu.</p><label>Dữ liệu<textarea v-model="input" rows="9" spellcheck="false"/></label><button type="button" @click="apply">Áp dụng</button><p v-if="error" role="alert">{{ error }}</p></details></figure></template>
<style scoped>
.prop-resolution{min-width:0}.prop-resolution label{display:grid;gap:6px}.prop-resolution :is(button,select,textarea){min-height:44px;padding:8px;max-width:100%;box-sizing:border-box;border:1px solid var(--control);border-radius:var(--radius);background:var(--paper);color:var(--ink);font:var(--fs-small)/1.7 var(--font-ui)}.prop-resolution :is(select,textarea){width:100%}.prop-resolution :is(button,select,textarea):focus-visible{outline:3px solid var(--tim);outline-offset:3px}.prop-resolution :is(p,li,summary){font:var(--fs-small)/1.7 var(--font-ui);overflow-wrap:anywhere}.resolution-status,.resolution-warning{padding:12px;border-left:3px solid var(--tim);background:var(--tim-soft)}.resolution-clauses{list-style:none;margin:0;padding:0!important;display:grid;gap:8px}.resolution-clauses li{display:grid;gap:4px;padding:10px;border:1px solid var(--rule);border-radius:var(--radius)}.resolution-clauses .active{border-color:var(--tim);background:var(--tim-soft)}.resolution-clauses .empty{border-left:3px solid var(--do)}.prop-resolution details{margin-top:16px}.prop-resolution summary{min-height:44px;cursor:pointer}.resolution-edit textarea{font:12px/1.7 var(--font-code);margin:8px 0}.prop-resolution button{cursor:pointer}@media(max-width:600px){.prop-resolution{padding:12px}}
</style>
